import * as BufferGeometryUtils from "https://esm.sh/three@0.183.2/examples/jsm/utils/BufferGeometryUtils.js?deps=three@0.183.2"
import { OrbitControls } from "https://esm.sh/three@0.183.2/examples/jsm/controls/OrbitControls.js?deps=three@0.183.2"
