// #region 1b. LAZY-LOADED DEPENDENCIES
// These are only pulled over the network the first time a feature that
// actually needs them is used (postprocessing FX, FBX import, ZIP model
// bundles, the debug Stats overlay, custom HDRIs). Keeping them out of the
// eager import graph is what the initial Lighthouse "unused JavaScript" /
// bootup-time cost was mostly coming from.
let _fbxLoaderModule = null
export function _loadFBXLoader() {
    if (!_fbxLoaderModule) {
        _fbxLoaderModule = import(
            "https://esm.sh/three@0.183.2/examples/jsm/loaders/FBXLoader.js?deps=three@0.183.2"
        ).then((m) => m.FBXLoader)
    }
    return _fbxLoaderModule
}

let _hdrLoaderModule = null
export function _loadHDRLoader() {
    if (!_hdrLoaderModule) {
        _hdrLoaderModule = import(
            "https://esm.sh/three@0.183.2/examples/jsm/loaders/HDRLoader.js?deps=three@0.183.2"
        ).then((m) => m.HDRLoader)
    }
    return _hdrLoaderModule
}

let _jsZipModule = null
export function _loadJSZip() {
    if (!_jsZipModule) {
        _jsZipModule = import("https://esm.sh/jszip@3.10.1").then(
            (m) => m.default || m
        )
    }
    return _jsZipModule
}

let _statsModule = null
export function _loadStats() {
    if (!_statsModule) {
        _statsModule = import("https://esm.sh/stats.js@0.17.0").then(
            (m) => m.default || m
        )
    }
    return _statsModule
}

let _postFxModules = null
export function _loadPostFxModules() {
    if (!_postFxModules) {
        _postFxModules = Promise.all([
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/EffectComposer.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/RenderPass.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/UnrealBloomPass.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/ShaderPass.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/SSAOPass.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/BokehPass.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/postprocessing/OutputPass.js?deps=three@0.183.2"
            ),
            import(
                "https://esm.sh/three@0.183.2/examples/jsm/shaders/FXAAShader.js?deps=three@0.183.2"
            ),
        ]).then(
            ([
                effectComposerMod,
                renderPassMod,
                bloomMod,
                shaderPassMod,
                ssaoMod,
                bokehMod,
                outputMod,
                fxaaMod,
            ]) => ({
                EffectComposer: effectComposerMod.EffectComposer,
                RenderPass: renderPassMod.RenderPass,
                UnrealBloomPass: bloomMod.UnrealBloomPass,
                ShaderPass: shaderPassMod.ShaderPass,
                SSAOPass: ssaoMod.SSAOPass,
                BokehPass: bokehMod.BokehPass,
                OutputPass: outputMod.OutputPass,
                FXAAShader: fxaaMod.FXAAShader,
            })
        )
    }
    return _postFxModules
}
// #endregion
